INSERT INTO `tbl_email_templates` (`template_id`, `template_key`, `template_name`, `subject`, `body_html`, `body_text`, `variables`, `is_active`, `created_at`, `updated_at`) VALUES
(1, 'trainee_account_created', 'Trainee Account Created', 'Your Hohoo-ville Account Credentials', '<h1>Welcome to Hohoo-ville</h1><p>Hello {{trainee_name}},</p><p>Username: {{username}}</p><p>Password: {{password}}</p>', 'Username: {{username}}\\nPassword: {{password}}', '[\"trainee_name\",\"username\",\"password\"]', 1, '2026-02-12 08:30:55', '2026-08-18 01:21:15'),
(2, 'enrollment_approved', 'Enrollment Approved', 'Your Enrollment Has Been Approved', '<p>Hello {{trainee_name}},</p><p>Your enrollment for {{course_name}} has been approved!</p><p>Batch: {{batch_name}}</p>', 'Your enrollment for {{course_name}} has been approved.\\nBatch: {{batch_name}}', '[\"trainee_name\",\"course_name\",\"batch_name\"]', 1, '2026-02-12 08:30:55', '2026-08-18 01:21:15'),
(3, NULL, 'Task Sheet Submission', 'New Task Sheet Submission from {{trainee_name}}', '<p>Task: {{task_name}}</p><p>Submitted on: {{submitted_date}}</p>', 'Task: {{task_name}}\\nSubmitted on: {{submitted_date}}', '[\"trainee_name\",\"task_name\",\"submitted_date\"]', 1, '2026-02-12 08:30:55', '2026-02-12 08:30:55'),
(4, NULL, 'Course Completion', 'Congratulations! Course Completed', '<p>Hello {{trainee_name}},</p><p>You have successfully completed {{course_name}}!</p><p>Score: {{final_score}}</p>', 'You have successfully completed {{course_name}}!\\nScore: {{final_score}}', '[\"trainee_name\",\"course_name\",\"final_score\"]', 1, '2026-02-12 08:30:55', '2026-02-12 08:30:55'),
(6, 'trainer_account_created', 'Trainer Account Created', 'Your Hohoo-ville Trainer Account Credentials', '<p>Hello {{user_name}},</p><p>Your trainer account is ready.</p><p>Username: {{username}}<br>Password: {{password}}</p>', 'Hello {{user_name}},Your trainer account is ready.Username: {{username}}Password: {{password}}', '[\"user_name\",\"user_email\",\"username\",\"password\",\"system_name\"]', 1, '2026-08-18 01:21:15', '2026-08-18 01:21:15'),
(8, 'application_rejected', 'Application Rejected', 'Application {{application_id}} - Rejected', '<p>Hello {{user_name}},</p><p>Your application for {{course_name}} was rejected.</p><p>Reason: {{rejection_reason}}</p>', 'Hello {{user_name}},Your application for {{course_name}} was rejected.Reason: {{rejection_reason}}', '[\"user_name\",\"user_email\",\"application_id\",\"course_name\",\"batch_name\",\"application_status\",\"rejection_reason\",\"application_date\",\"date\",\"system_name\"]', 1, '2026-08-18 01:21:15', '2026-08-18 01:21:15'),
(9, 'application_qualified', 'Application Qualified', 'Your application passed initial review', '<p>Hello {{user_name}},</p><p>Your application for {{course_name}} has passed initial review.</p>', 'Hello {{user_name}},Your application for {{course_name}} has passed initial review.', '[\"user_name\",\"user_email\",\"application_id\",\"course_name\",\"batch_name\",\"application_status\",\"application_date\",\"date\",\"system_name\"]', 1, '2026-08-18 01:21:15', '2026-08-18 01:21:15');
